var MODULE_LOAD_TIME = new Date().getTime() - MODULE_LOAD_START;
$.writeln("🎉 InDesign DOM Discovery Builder v3.1 - All " + MODULES_LOADED.length + " modules loaded successfully!");
$.writeln("⚡ Total load time: " + MODULE_LOAD_TIME + "ms");
if (MODULES_LOADED.length === 11) {
    $.writeln("✅ Auto-discovery build verification passed - ready for use");
    
    // Auto-start DOM Discovery interface
    try {
        $.writeln("🚀 Starting DOM Discovery interface...");
        if (typeof showAdvancedUI === "function") {
            showAdvancedUI();
        } else if (typeof showDOMVisualizer === "function") {
            showDOMVisualizer();
        } else if (typeof showDOMExplorer === "function") {
            showDOMExplorer();
        } else {
            $.writeln("⚠️  DOM interface functions not found - manual start required");
            $.writeln("💡 Try running showAdvancedUI() or showDOMVisualizer() manually");
        }
    } catch (exc) {
        $.writeln("❌ Auto-start failed: " + exc.message);
        $.writeln("💡 Try running showAdvancedUI() manually");
    }
} else {
    $.writeln("⚠️  Module count mismatch - check for loading errors");
}
